tape( 'the function supports providing offsets', function test( t ) {
	var expected;
	var out;
	var D;
	var E;

	// D contains a leading zero element
	D = new Float64Array( [ 0.0, 4.0, -2.0, 5.0, -1.0 ] );
	E = new Float64Array( [ 0.0, 1.0, -3.0, 2.0 ] );

	out = dlanst( 'max', 4, D, 1, 1, E, 1, 1 );
	t.strictEqual( out, 5.0, 'returns expected value' );

	out = dlanst( 'one-norm', 4, D, 1, 1, E, 1, 1 );
	t.strictEqual( out, 10.0, 'returns expected value' );

	out = dlanst( 'infinity-norm', 4, D, 1, 1, E, 1, 1 );
	t.strictEqual( out, 10.0, 'returns expected value' );

	expected = sqrt( 74.0 );
	out = dlanst( 'frobenius-norm', 4, D, 1, 1, E, 1, 1 );
	t.strictEqual( out, expected, 'returns expected value' );

	t.end();
});

tape( 'the function supports negative strides', function test( t ) {
	var expected;
	var out;
	var D;
	var E;

	// Reversed arrays with negative strides
	D = new Float64Array( [ -1.0, 5.0, -2.0, 4.0 ] );
	E = new Float64Array( [ 2.0, -3.0, 1.0 ] );

	out = dlanst( 'max', 4, D, -1, 3, E, -1, 2 );
	t.strictEqual( out, 5.0, 'returns expected value' );

	out = dlanst( 'one-norm', 4, D, -1, 3, E, -1, 2 );
	t.strictEqual( out, 10.0, 'returns expected value' );

	out = dlanst( 'infinity-norm', 4, D, -1, 3, E, -1, 2 );
	t.strictEqual( out, 10.0, 'returns expected value' );

	expected = sqrt( 74.0 );
	out = dlanst( 'frobenius-norm', 4, D, -1, 3, E, -1, 2 );
	t.strictEqual( out, expected, 'returns expected value' );

	t.end();
});

tape( 'the function supports large strides', function test( t ) {
	var expected;
	var out;
	var D;
	var E;

	// D has stride 2: elements at indices 0, 2, 4, 6
	D = new Float64Array( [ 4.0, 999.0, -2.0, 999.0, 5.0, 999.0, -1.0 ] );

	// E has stride 2: elements at indices 0, 2, 4
	E = new Float64Array( [ 1.0, 999.0, -3.0, 999.0, 2.0 ] );

	out = dlanst( 'max', 4, D, 2, 0, E, 2, 0 );
	t.strictEqual( out, 5.0, 'returns expected value' );

	out = dlanst( 'one-norm', 4, D, 2, 0, E, 2, 0 );
	t.strictEqual( out, 10.0, 'returns expected value' );

	out = dlanst( 'infinity-norm', 4, D, 2, 0, E, 2, 0 );
	t.strictEqual( out, 10.0, 'returns expected value' );

	expected = sqrt( 74.0 );
	out = dlanst( 'frobenius-norm', 4, D, 2, 0, E, 2, 0 );
	t.strictEqual( out, expected, 'returns expected value' );

	t.end();
});

tape( 'the function supports combined offsets and strides', function test( t ) {
	var expected;
	var out;
	var D;
	var E;

	// D at offset 1, stride 2: indices 1, 3, 5, 7
	D = new Float64Array( [ 999.0, 4.0, 999.0, -2.0, 999.0, 5.0, 999.0, -1.0 ] );

	// E at offset 1, stride 2: indices 1, 3, 5
	E = new Float64Array( [ 999.0, 1.0, 999.0, -3.0, 999.0, 2.0 ] );

	out = dlanst( 'max', 4, D, 2, 1, E, 2, 1 );
	t.strictEqual( out, 5.0, 'returns expected value' );

	out = dlanst( 'one-norm', 4, D, 2, 1, E, 2, 1 );
	t.strictEqual( out, 10.0, 'returns expected value' );

	expected = sqrt( 74.0 );
	out = dlanst( 'frobenius-norm', 4, D, 2, 1, E, 2, 1 );
	t.strictEqual( out, expected, 'returns expected value' );

	t.end();
});

