tape( 'the function propagates NaN in max norm', function test( t ) {
	var out;
	var D;
	var E;

	D = new Float64Array( [ 1.0, NaN, 3.0 ] );
	E = new Float64Array( [ 2.0, 4.0 ] );

	out = dlanst( 'max', 3, D, 1, 0, E, 1, 0 );
	t.strictEqual( isnan( out ), true, 'returns expected value' );

	t.end();
});

