tape( 'the function supports infinite values', function test( t ) {
	var out;
	var D;
	var E;

	D = new Float64Array( [ 1.0, PINF, 3.0 ] );
	E = new Float64Array( [ 2.0, 4.0 ] );

	out = dlanst( 'max', 3, D, 1, 0, E, 1, 0 );
	t.strictEqual( out, PINF, 'returns expected value' );

	out = dlanst( 'one-norm', 3, D, 1, 0, E, 1, 0 );
	t.strictEqual( out, PINF, 'returns expected value' );

	out = dlanst( 'infinity-norm', 3, D, 1, 0, E, 1, 0 );
	t.strictEqual( out, PINF, 'returns expected value' );

	out = dlanst( 'frobenius-norm', 3, D, 1, 0, E, 1, 0 );
	t.strictEqual( out, PINF, 'returns expected value' );

	t.end();
});

