tape( 'the function computes the Frobenius norm (larger matrix)', function test( t ) {
	var expected;
	var out;
	var D;
	var E;

	D = new Float64Array( [ 2.0, -1.0, 3.0, 4.0, -2.0 ] );
	E = new Float64Array( [ 1.0, -2.0, 1.0, 3.0 ] );

	expected = 8.0;

	out = dlanst( 'frobenius-norm', 5, D, 1, 0, E, 1, 0 );
	t.strictEqual( out, expected, 'returns expected value' );

	t.end();
});

tape( 'the function computes the Frobenius norm without intermediate overflow', function test( t ) {
	var expected;
	var out;
	var D;
	var E;

	D = new Float64Array( [ 1.0e300, -1.0e300, 1.0e300 ] );
	E = new Float64Array( [ 1.0e300, -1.0e300 ] );

	// sqrt( 3*(1e300)^2 + 2*2*(1e300)^2 ) = sqrt(7)*1e300:
	expected = sqrt( 7.0 ) * 1.0e300;

	out = dlanst( 'frobenius-norm', 3, D, 1, 0, E, 1, 0 );
	t.strictEqual( out, expected, 'returns expected value' );

	t.end();
});

tape( 'the function computes the Frobenius norm without intermediate underflow', function test( t ) {
	var expected;
	var out;
	var D;
	var E;

	D = new Float64Array( [ 1.0e-300, -1.0e-300, 1.0e-300 ] );
	E = new Float64Array( [ 1.0e-300, -1.0e-300 ] );

	// sqrt( 3*(1e-300)^2 + 2*2*(1e-300)^2 ) = sqrt(7)*1e-300:
	expected = sqrt( 7.0 ) * 1.0e-300;

	out = dlanst( 'frobenius-norm', 3, D, 1, 0, E, 1, 0 );
	t.strictEqual( out, expected, 'returns expected value' );

	t.end();
});
